from numpy.linalg import lstsq
import itertools
t=df['t'];P=df['P'];y=df['dP_dt']
fT={'1':np.ones_like(t),'t':t,'t2':t**2,'sqrt':np.sqrt(t),'log':np.log(t),'exp-t':np.exp(-t),'exp-.5t':np.exp(-0.5*t),'1/t':1/t,'sin':np.sin(t),'cos':np.cos(t),'exp-.2t':np.exp(-0.2*t),'t1.5':t**1.5}
fP={'1':np.ones_like(P),'P':P,'P2':P**2,'logP':np.log(P),'sqrtP':np.sqrt(P),'expP':np.exp(-P),'P3':P**3,'1/P':1/P,'P*expP':P*np.exp(-P)}
terms={a+'|'+b:fT[a]*fP[b] for a,b in itertools.product(fT,fP)}
keys=list(terms); M=np.array([terms[k] for k in keys]).T
ss=np.sum((y-y.mean())**2)
res=[]
for c in np.linspace(0.3,0.8,11):
    base=P*np.exp(-c*P)*t**1.5
    for i in range(len(keys)):
        for j in range(i+1,len(keys)):
            B=np.c_[base,M[:,i],M[:,j]]
            co=lstsq(B,y,rcond=None)[0]
            r=np.sum((B@co-y)**2)/ss
            res.append((r,round(c,2),keys[i],keys[j]))
res.sort(key=lambda x:x[0])
for x in res[:10]: print(x)
